import React, { useEffect } from "react";
import { Link, useLocation } from "react-router-dom";
import { FormattedMessage } from "react-intl";
import Loader from "react-loader-spinner";

// Redux
import { connect } from "react-redux";
import { fetchVisaPostingDetails } from "../../../actions/filesets";
// Components
import { Card, CardBody, CardHeader, Col, Row, Table } from "reactstrap";
import ErrorMessage from "../../../components/ErrorMessage";

const VisaPostingDetails = ({
	// url params
	match                   : { params: { id } },
	// action creators
	fetchVisaPostingDetails,
	// props from reducer
	visaPostingDetailsError,
	visaPostingDetails,
}) => {
	const Location = useLocation();

	useEffect(() => {
		fetchVisaPostingDetails(id);
	}, []);

	let postingItemDetails = [];
	Object.entries(visaPostingDetails ? visaPostingDetails.data : {}).forEach(([ key, value ]) => {
		let itemObj = {};
		itemObj.key = key;
		itemObj.value = value;
		postingItemDetails = postingItemDetails.concat(itemObj);
		return postingItemDetails;
	});

	postingItemDetails = postingItemDetails.filter(
		(item) =>
			item.key !== "id" &&
			item.key !== "filename" &&
			item.key !== "issuerRrnFlexCubeReady" &&
			item.key !== "acquirerRrnReady" &&
			item.key !== "postingMap" &&
			item.key !== "completed" &&
			item.key !== "posting",
	);

	let postingEntries = visaPostingDetails && visaPostingDetails.data.postingMap;
	let postingMap = [];
	Object.entries(postingEntries ? postingEntries : []).forEach(([ key, value ]) => {
		let itemObj = {};
		itemObj.key = key;
		itemObj.value = value;
		postingMap = postingMap.concat(itemObj);
		return postingMap;
	});

	const completedEntries = visaPostingDetails && visaPostingDetails.data.completed;
	const settlementDate = visaPostingDetails && visaPostingDetails.data.batchDate;

	return (
		<div className='animated fadeIn'>
			<Row>
				{/* Handle Loading */}
				{!visaPostingDetailsError &&
				!visaPostingDetails && (
					<Col className={"col-12"}>
						<Card>
							<CardBody>
								<Loader
									type='ThreeDots'
									color='#337AB7'
									height={100}
									width={100}
									style={{ textAlign: "center" }}
								/>
							</CardBody>
						</Card>
					</Col>
				)}

				{/* Handle Error display */}
				{visaPostingDetailsError &&
				visaPostingDetailsError.data && (
					<Col className={"col-12"}>
						<Card>
							<CardHeader>
								<strong>Error</strong>
							</CardHeader>
							<CardBody>
								<ErrorMessage message={visaPostingDetailsError.data.message} />
							</CardBody>
						</Card>
					</Col>
				)}

				{/* Handle display all content */}
				{!visaPostingDetailsError &&
				visaPostingDetails &&
				visaPostingDetails.data && (
					<Col className={"col-12"}>
						<Row className={"mb-5"}>
							<Col className={"col-4"}>
								<Card className={"h-100"}>
									<CardHeader>
										<strong>
											<FormattedMessage id='Posting Details' defaultMessage='Posting Details' />
										</strong>
									</CardHeader>
									<CardBody>
										{/* Handle display */}
										{/* Handle header display */}
										{!visaPostingDetailsError &&
										visaPostingDetails &&
										visaPostingDetails.data && (
											<article>
												{postingItemDetails.map((itemDetail, index) => {
													return (
														<div
															key={index}
															className={
																"d-flex justify-content-between align-items-center p-2"
															}
														>
															<span>
																<strong>
																	<FormattedMessage
																		id={itemDetail.key ? itemDetail.key : "N/A"}
																		defaultMessage={
																			itemDetail.key ? itemDetail.key : "N/A"
																		}
																	/>
																</strong>
															</span>{" "}
															<span>
																<FormattedMessage
																	id={itemDetail.value ? itemDetail.value : "N/A"}
																	defaultMessage={
																		itemDetail.value ? itemDetail.value : "N/A"
																	}
																/>
															</span>
														</div>
													);
												})}
											</article>
										)}
									</CardBody>
								</Card>
							</Col>
							<Col className={"col-5"}>
								<Card className={"h-100"}>
									<CardHeader className={"d-flex justify-content-between align-item-center w-100"}>
										<strong>
											<FormattedMessage id='Posting Entries' defaultMessage='Posting Entries' />
										</strong>
									</CardHeader>
									<CardBody>
										{/* Handle no posting entries */}
										{postingEntries &&
										Object.keys(postingEntries).length < 1 && (
											<ErrorMessage message={"No posting entries for this affiliate"} />
										)}
										{/* Handle display */}
										{/* Handle header display */}
										{postingEntries &&
										Object.keys(postingEntries).length > 0 && (
											<Table bordered striped hover size='sm'>
												<thead>
													<tr>
														<th colSpan={2}>
															<FormattedMessage
																id={"Affiliate Posting Entries"}
																defaultMessage={"Affiliate Posting Entries"}
															/>
														</th>
													</tr>
												</thead>
												<tbody>
													{postingMap.map((entries, index) => {
														return (
															<tr key={index}>
																<td>
																	<FormattedMessage
																		id={entries.key}
																		defaultMessage={entries.key}
																	/>
																</td>
																<td>
																	<Link
																		style={{ textDecoration: "none" }}
																		// to={`/admin/${settlementDate}/query-posting-records`}
																		to={{
																			pathname : `/admin/${settlementDate}/query-posting-records`,
																			search   : `?posting-log-id=${entries.value}&affiliateCode=${entries.key}&page=1`,
																			state    : {
																				backUrl : `${Location.pathname}`,
																			},
																		}}
																	>
																		<FormattedMessage
																			id={"View Posting Entries"}
																			defaultMessage={"View Posting Entries"}
																		/>
																	</Link>
																</td>
															</tr>
														);
													})}
												</tbody>
											</Table>
										)}
									</CardBody>
								</Card>
							</Col>
							<Col className={"col-3"}>
								<Card className={"h-100"}>
									<CardHeader>
										<strong>
											<FormattedMessage id='Completed' defaultMessage='Completed' />
										</strong>
									</CardHeader>
									<CardBody>
										{/* Handle no posting entries */}
										{completedEntries &&
										completedEntries.length === 0 && (
											<ErrorMessage message={"No posting entries for this affiliate"} />
										)}
										{completedEntries &&
										completedEntries.length > 0 && (
											<Table bordered striped hover size='sm'>
												<thead>
													<tr>
														<th colSpan={2}>
															<FormattedMessage
																id={"Affiliate List"}
																defaultMessage={"Affiliate List"}
															/>
														</th>
													</tr>
												</thead>
												<tbody>
													{completedEntries.map((entries, index) => {
														return (
															<tr key={index}>
																<td>
																	<FormattedMessage
																		id={entries}
																		defaultMessage={entries}
																	/>
																</td>
																<td>
																	<span className={"text-success"}>
																		<strong>
																			<i
																				className='fa fa-check'
																				aria-hidden='true'
																			/>
																		</strong>
																	</span>
																</td>
															</tr>
														);
													})}
												</tbody>
											</Table>
										)}
									</CardBody>
								</Card>
							</Col>
						</Row>
					</Col>
				)}
			</Row>
		</div>
	);
};

const mapStateToProps = (state) => {
	return {
		visaPostingDetailsError : state.fileSets.visaPostingDetailsError,
		visaPostingDetails      : state.fileSets.visaPostingDetails,
	};
};

export default connect(mapStateToProps, { fetchVisaPostingDetails })(VisaPostingDetails);
